const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[name]||ICONS.rect}"/></svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)});root.querySelectorAll('button[title]').forEach(el=>{el.setAttribute('aria-label',el.title)})}
const kindIcon=n=>({frame:'frame',group:'group',component:'component',instance:'instance',path:'path',image:'image',note:'note',line:'line',text:'text',ellipse:'ellipse'}[typeof n==='string'?n:n.type]||'rect');
let doc=M.createSample();doc.id=M.uid();let pageId=doc.pages[0].id,selection=[],records=[],recordMap=new Map(),view={x:0,y:0,zoom:1},tool='select',leftTab='layers',rightTab='design',collapsed=new Set(),snap=true,grid=false,rulers=false,spaceDown=false,drag=null,hoverId=null,penPoints=[],penPointer=null,vectorEdit=null,clipboard=null,editingId=null,history=[],future=[],historyBefore=null,scheduled=false,dirty=true,saveTimer=0,toastTimer=0,activeMenu=false,engine,saveEpoch=0,assetsReplacement=null,presentIndex=0,previousFocus=null;
