const palette=['#386CE8','#7894C3','#DCE8FC','#202D45','#929EAF','#FFFFFF','#EAC995','#7FAD97'];
function renderAssets(){const assets=[['button','主要按钮','<span class="demo-btn">开始探索 →</span>'],['tag','状态标签','<span class="demo-tag">进行中</span>'],['card','信息卡片','<span class="demo-card"></span>'],['avatar','用户头像','<span class="demo-avatar">墨</span>']];const comps=[];for(const p of doc.pages)M.walk(p.children,n=>{if(n.type==='component')comps.push(n)});$('#assetsPanel').innerHTML=`<p class="assets-intro">常用构件，轻松复用。<br>点击插入，所有内容都可继续编辑。</p><div class="asset-heading">基础构件</div><div class="asset-grid">${assets.map(([id,name,v])=>`<button class="asset-item" data-asset="${id}" draggable="true"><div class="asset-preview">${v}</div><div class="asset-name">${name}</div></button>`).join('')}</div><div class="asset-heading">项目色彩</div><div class="asset-colors">${palette.map(c=>`<button data-assetcolor="${c}" style="background:${c}" title="${c}"></button>`).join('')}</div><div class="asset-heading">本地组件 <span class="badge">${comps.length}</span></div>${comps.map(n=>`<button class="inline-action" data-instance="${n.id}" style="justify-content:flex-start;padding:0 9px;color:#8D69BD">${icon('component')}${M.esc(n.name)}</button>`).join('')||'<p class="muted-note">选中图层，按 ⌥ ⌘ K 创建组件。</p>'}<button class="inline-action" data-action="import-image" style="margin-top:20px">${icon('image')}置入本地图片</button>`;hydrate($('#assetsPanel'))}
function renderAll(){$('#documentName').value=doc.name;document.title=`${doc.name} — 墨构 MOKO`;renderPages();renderLayers();renderInspector();if(leftTab==='assets')renderAssets();updateUndo()}
function fitBounds(b,padding=65){const w=viewport.clientWidth,h=viewport.clientHeight;view.zoom=M.clamp(Math.min((w-padding*2)/Math.max(b.w,1),(h-190)/Math.max(b.h,1)),.03,4);view.x=(w-b.w*view.zoom)/2-b.x*view.zoom;view.y=65-b.y*view.zoom;requestDraw()}
function fitAll(){const items=page().children.filter(n=>n.visible!==false);if(!items.length){view={x:100,y:100,zoom:1};requestDraw();return}fitBounds(M.union(items.map(n=>recordMap.get(n.id)?.bounds).filter(Boolean)))}
function zoomAt(factor,at={x:viewport.clientWidth/2,y:viewport.clientHeight/2}){finishText();const p=world(at);view.zoom=M.clamp(view.zoom*factor,.03,16);view.x=at.x-p.x*view.zoom;view.y=at.y-p.y*view.zoom;requestDraw();scheduleSave()}
function setTool(t){finishText();if(tool==='pen'&&penPoints.length)finishPen(false);tool=t;vectorEdit=null;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));overlay.style.cursor=t==='hand'?'grab':t==='text'?'text':['rect','ellipse','line','pen','frame','comment'].includes(t)?'crosshair':'default';requestDraw()}
function addNode(n,parent=null){(parent?.children||page().children).push(n);refreshRecords();selection=[n.id];return n}
function centerWorld(){return world({x:viewport.clientWidth/2,y:viewport.clientHeight/2-40})}
function createFrame(w=375,h=812){const c=centerWorld();edit(()=>{addNode(M.node('frame',{name:`画板 ${w} × ${h}`,x:Math.round(c.x-w/2),y:Math.round(c.y-h/2),w,h,fill:'#FFFFFF',clip:true,children:[]}))});setTool('select')}
function resizeChildren(n,oldW,oldH,scaleAll=false){if(!n.children||n.layout&&n.layout!=='none')return;const sx=n.w/oldW,sy=n.h/oldH,dx=n.w-oldW,dy=n.h-oldH;for(const c of n.children){const cw=c.w,ch=c.h;if(scaleAll){c.x*=sx;c.y*=sy;c.w=Math.max(1,c.w*sx);c.h=Math.max(1,c.h*sy);if(c.fontSize)c.fontSize*=Math.min(sx,sy);if(c.points){for(const p of c.points){p.x*=sx;p.y*=sy;if(p.in){p.in.x*=sx;p.in.y*=sy}if(p.out){p.out.x*=sx;p.out.y*=sy}}}resizeChildren(c,cw,ch,true)}else{if(c.constraintX==='right')c.x+=dx;if(c.constraintX==='center')c.x+=dx/2;if(c.constraintX==='stretch')c.w=Math.max(1,c.w+dx);if(c.constraintX==='scale'){c.x*=sx;c.w=Math.max(1,c.w*sx)}if(c.constraintY==='bottom')c.y+=dy;if(c.constraintY==='center')c.y+=dy/2;if(c.constraintY==='stretch')c.h=Math.max(1,c.h+dy);if(c.constraintY==='scale'){c.y*=sy;c.h=Math.max(1,c.h*sy)}M.autoText(c);resizeChildren(c,cw,ch,false)}}}
function setOverride(n,key,value){let cur=n,parent=M.find(page().children,cur.id)?.parent;if(n.type==='instance'){n.overrides??={};n.overrides._root??={};n.overrides._root[key]=M.clone(value);return}while(parent){if(parent.type==='instance'){parent.overrides??={};if(n.sourceId){parent.overrides[n.sourceId]??={};parent.overrides[n.sourceId][key]=M.clone(value)}break}cur=parent;parent=M.find(page().children,cur.id)?.parent}}
function syncInstances(){const masters=new Map();for(const p of doc.pages)M.walk(p.children,n=>{if(n.type==='component')masters.set(n.id,n)});for(const p of doc.pages)M.walk(p.children,n=>{if(n.type!=='instance')return;const master=masters.get(n.masterId);if(!master)return;const oldMap=new Map();M.walk(n.children||[],c=>{if(c.sourceId)oldMap.set(c.sourceId,c)});function cp(source){const c=M.clone(source);c.sourceId=source.id;c.id=oldMap.get(source.id)?.id||M.uid();if(source.children)c.children=source.children.map(cp);Object.assign(c,n.overrides?.[source.id]||{});M.autoText(c);return c}n.children=(master.children||[]).map(cp);for(const key of ['w','h','fill','fillEnabled','fill2','gradient','stroke','strokeWidth','radius','layout','gap','padding','crossAlign','hug','clip'])if(master[key]!==undefined)n[key]=master[key];Object.assign(n,n.overrides?._root||{})})}
function property(key,value,{live=false}={}){if(!selection.length)return;const mutate=()=>{for(const n of selectedNodes()){if(recordMap.get(n.id)?.locked&&key!=='locked'&&key!=='visible')continue;const oldW=n.w,oldH=n.h;let v=value;if(key==='opacity')v=M.clamp(+value/100,0,1);else if(key==='shadow.opacity')v=M.clamp(+value/100,0,1);else if(['x','y','w','h','radius','rotation','strokeWidth','fontWeight','fontSize','lineHeight','letterSpacing','gap','padding','shadow.x','shadow.y','shadow.blur'].includes(key)){v=Number(value);if(!Number.isFinite(v))continue;if(['w','h','fontSize'].includes(key))v=M.clamp(v,1,100000);if(['radius','strokeWidth','gap','padding','shadow.blur'].includes(key))v=M.clamp(v,0,10000);if(key==='lineHeight')v=M.clamp(v,.3,10)}if(['fill','fill2','stroke'].includes(key)&&!/^#[0-9a-f]{6}$/i.test(v))continue;if(key.startsWith('shadow.')){n.shadow??={x:0,y:6,blur:16,opacity:.16,color:'#243653'};n.shadow[key.split('.')[1]]=v;setOverride(n,'shadow',n.shadow)}else{n[key]=v;setOverride(n,key,v)}if(key==='layout'&&v!=='none'){n.gap??=12;n.padding??=16;n.crossAlign??='start';n.hug??=false}if(key==='w'||key==='h'){if(n.type==='path'&&n.points){const sx=n.w/oldW,sy=n.h/oldH;for(const p of n.points){p.x*=sx;p.y*=sy;if(p.in){p.in.x*=sx;p.in.y*=sy}if(p.out){p.out.x*=sx;p.out.y*=sy}}}if(key==='h'&&n.type==='text')n.autoHeight=false;resizeChildren(n,oldW,oldH,n.type==='group')}if(n.type==='text'&&key!=='h')M.autoText(n)}};if(live){beginHistory();mutate();M.applyLayout({children:page().children});refreshRecords();requestDraw()}else edit(mutate)}
function groupSelection(auto=false){const nodes=selectedNodes();if(!nodes.length)return;edit(()=>{let parents=nodes.map(n=>M.find(page().children,n.id)?.parent),parent=parents.every(p=>p===parents[0])?parents[0]:null;const pm=parent?recordMap.get(parent.id).matrix:M.identity();const copies=nodes.map(n=>({n,m:recordMap.get(n.id).matrix}));let b=M.union(copies.map(({n,m})=>M.fromPoints(M.corners(n,M.mul(M.invert(pm),m)))));for(const {n,m} of copies){const f=M.find(page().children,n.id);f.siblings.splice(f.siblings.indexOf(n),1);M.moveToParent(n,m,pm);n.x-=b.x;n.y-=b.y}const g=M.node(auto?'frame':'group',{name:auto?'自动布局':'编组',x:b.x,y:b.y,w:Math.max(1,b.w),h:Math.max(1,b.h),fillEnabled:false,children:copies.map(c=>c.n),...(auto?{layout:'vertical',padding:16,gap:12,crossAlign:'start',hug:true,w:b.w+32}:{} )});(parent?.children||page().children).push(g);selection=[g.id];collapsed.delete(g.id)});toast(auto?'已添加自动布局 · 修改间距即可重新排版':'已将所选图层编组')}
function ungroupSelection(){const nodes=selectedNodes().filter(n=>n.children&&n.type!=='instance');if(!nodes.length){toast('请选择一个编组或画板');return}edit(()=>{const newIds=[];for(const n of nodes){const f=M.find(page().children,n.id),parent=f.parent;const parentMatrix=parent?recordMap.get(parent.id).matrix:M.identity();let pos=f.siblings.indexOf(n);const children=n.children;for(const c of children){M.moveToParent(c,recordMap.get(c.id).matrix,parentMatrix);newIds.push(c.id)}f.siblings.splice(pos,1,...children)}selection=newIds})}
function deleteSelection(){const nodes=selectedNodes();if(!nodes.length)return;edit(()=>{for(const n of nodes){if(recordMap.get(n.id)?.locked)continue;const f=M.find(page().children,n.id);if(f)f.siblings.splice(f.siblings.indexOf(n),1)}selection=[]});toast('图层已删除 · ⌘ / Ctrl Z 可撤销')}
function duplicate(){const nodes=selectedNodes();if(!nodes.length)return;edit(()=>{const ids=[];for(const n of nodes){const f=M.find(page().children,n.id),copy=M.renew(n);copy.name=n.name+' 副本';copy.x+=20;copy.y+=20;f.siblings.splice(f.siblings.indexOf(n)+1,0,copy);ids.push(copy.id)}selection=ids});toast('已复制图层')}
function order(action){if(!selection.length)return;edit(()=>{for(const n of selectedNodes()){const f=M.find(page().children,n.id),i=f.siblings.indexOf(n);f.siblings.splice(i,1);const index=action==='front'?f.siblings.length:action==='back'?0:action==='forward'?Math.min(f.siblings.length,i+1):Math.max(0,i-1);f.siblings.splice(index,0,n)}})}
function moveRecordWorld(r,dx,dy){const parentMatrix=r.parent?recordMap.get(r.parent.id)?.matrix:M.identity();const delta=M.vector(M.invert(parentMatrix),{x:dx,y:dy});r.node.x+=delta.x;r.node.y+=delta.y}
function align(action){if(!selection.length)return;edit(()=>{const rs=selectedRecords();let b;if(rs.length>1)b=M.union(rs.map(r=>r.bounds));else if(rs[0].parent)b=recordMap.get(rs[0].parent.id).bounds;else b={x:-view.x/view.zoom,y:-view.y/view.zoom,w:viewport.clientWidth/view.zoom,h:viewport.clientHeight/view.zoom};for(const r of rs){if(r.locked)continue;let dx=0,dy=0;if(action==='left')dx=b.x-r.bounds.x;if(action==='right')dx=b.x+b.w-r.bounds.x-r.bounds.w;if(action==='center')dx=b.x+b.w/2-r.bounds.x-r.bounds.w/2;if(action==='top')dy=b.y-r.bounds.y;if(action==='bottom')dy=b.y+b.h-r.bounds.y-r.bounds.h;if(action==='middle')dy=b.y+b.h/2-r.bounds.y-r.bounds.h/2;moveRecordWorld(r,dx,dy)}})}
function distribute(direction){const rs=selectedRecords();if(rs.length<3){toast('至少选择 3 个图层，才能等距分布');return}edit(()=>{const hor=direction==='horizontal',k=hor?'x':'y',size=hor?'w':'h';rs.sort((a,b)=>a.bounds[k]-b.bounds[k]);const first=rs[0].bounds[k],last=rs.at(-1).bounds[k]+rs.at(-1).bounds[size],total=rs.reduce((s,r)=>s+r.bounds[size],0),gap=(last-first-total)/(rs.length-1);let cursor=first;for(const r of rs){const d=cursor-r.bounds[k];moveRecordWorld(r,hor?d:0,hor?0:d);cursor+=r.bounds[size]+gap}})}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{const ta=document.createElement('textarea');ta.value=text;ta.style.cssText='position:fixed;left:-99999px';document.body.appendChild(ta);ta.select();let ok=false;try{ok=document.execCommand('copy')}catch{}ta.remove();return ok}}
function copySelection(cut=false){if(!selection.length)return;clipboard=selectedRecords().map(r=>{const n=M.clone(r.node);M.moveToParent(n,r.matrix,M.identity());return n});copyText('MOKO_CLIPBOARD\n'+JSON.stringify(clipboard));if(cut)deleteSelection();else toast('已复制，可粘贴到任意墨构页面')}
function pasteNodes(nodes=clipboard,at=null){if(!nodes?.length)return;try{M.validateDocument({version:1,pages:[{id:'clipboard',name:'粘贴',children:nodes}]})}catch(e){toast(e.message);return}edit(()=>{const copies=nodes.map(M.renew);const b=M.union(copies.map(n=>M.fromPoints(M.corners(n,M.localMatrix(n)))));const pos=at||centerWorld();for(const n of copies){n.x+=pos.x-b.x-b.w/2;n.y+=pos.y-b.y-b.h/2;page().children.push(n)}selection=copies.map(n=>n.id)});setTool('select')}
function makeComponent(){if(!selection.length)return;if(selection.length>1)groupSelection();edit(()=>{let n=selectedNodes()[0];if(!n.children){const r=recordMap.get(n.id),f=M.find(page().children,n.id),idx=f.siblings.indexOf(n);const master=M.node('component',{name:'组件 / '+n.name,x:n.x,y:n.y,w:n.w,h:n.h,rotation:n.rotation,fillEnabled:false,children:[n]});n.x=0;n.y=0;n.rotation=0;f.siblings.splice(idx,1,master);selection=[master.id]}else{n.type='component';n.name='组件 / '+n.name}});toast('已创建主组件，可在资源面板复用')}
function createInstance(id=null,at=null){const masterId=id||selection[0];let master=null;for(const p of doc.pages){const f=M.find(p.children,masterId);if(f){master=f.node;break}}if(!master||master.type!=='component'){toast('请选择一个主组件');return}edit(()=>{const c=at||centerWorld();const n=M.node('instance',{name:master.name+' · 实例',x:c.x-master.w/2,y:c.y-master.h/2,w:master.w,h:master.h,masterId:master.id,children:[],overrides:{}});addNode(n);syncInstances()});toast('已创建与主组件关联的实例')}
function insertAsset(kind,at=null){const c=at||centerWorld();edit(()=>{const t=(txt,w,size=13,fill='#fff')=>{const n=M.node('text',{name:txt,text:txt,w,h:size*1.5,fontSize:size,fontFamily:M.FONT,lineHeight:1.5,fill,autoHeight:true,textAlign:'center'});M.autoText(n);return n};let n;if(kind==='button')n=M.node('frame',{name:'主要按钮',w:200,h:44,fill:'#386CE8',radius:9,layout:'horizontal',padding:12,gap:0,crossAlign:'center',children:[t('开始探索 →',176)]});else if(kind==='tag')n=M.node('frame',{name:'状态标签',w:88,h:30,fill:'#E5EEFF',radius:15,layout:'horizontal',padding:10,gap:0,crossAlign:'center',children:[t('进行中',68,11,'#587EC5')]});else if(kind==='avatar')n=M.node('frame',{name:'用户头像',w:52,h:52,fill:'#DCE8FC',radius:26,layout:'horizontal',padding:8,gap:0,crossAlign:'center',children:[t('墨',36,21,'#6C8EBF')]});else{const a=t('让好想法，自然生长',216,17,'#24324A');a.textAlign='left';const b=t('从一个小小的灵感开始。',216,12,'#909DAF');b.textAlign='left';n=M.node('frame',{name:'信息卡片',w:256,h:140,fill:'#FFFFFF',radius:14,layout:'vertical',padding:20,gap:13,crossAlign:'start',children:[a,b],shadow:{x:0,y:5,blur:18,opacity:.08,color:'#243653'}})}n.x=c.x-n.w/2;n.y=c.y-n.h/2;addNode(n)});setTool('select')}
function renameNode(id=selection[0]){const n=M.find(page().children,id)?.node;if(!n)return;showModal('重命名图层',`<input id="renameInput" class="search-input" value="${M.esc(n.name)}" maxlength="120" aria-label="图层名称"><div class="modal-footer"><button data-action="close-modal">取消</button><button class="primary" id="renameConfirm">保存名称</button></div>`);const inp=$('#renameInput');inp.focus();inp.select();const apply=()=>{const value=inp.value.trim();if(value){edit(()=>n.name=value);hideModal()}};$('#renameConfirm').onclick=apply;inp.onkeydown=e=>{if(e.key==='Enter')apply()}}
function switchPage(id){finishText();if(!doc.pages.some(p=>p.id===id))return;pageId=id;selection=[];penPoints=[];vectorEdit=null;refreshRecords();fitAll();renderAll();scheduleSave()}
function addPage(){edit(()=>{const p={id:M.uid(),name:'新页面 '+(doc.pages.length+1),children:[]};doc.pages.push(p);pageId=p.id;selection=[];view={x:viewport.clientWidth/2,y:viewport.clientHeight/2,zoom:1}});toast('已创建新页面 · 双击页面名称可重命名')}
function removePage(id){if(doc.pages.length<2)return;const p=doc.pages.find(p=>p.id===id);if(!p)return;showModal('删除页面',`<p>删除「${M.esc(p.name)}」及其中的全部图层？删除后可以撤销。</p><div class="modal-footer"><button data-action="close-modal">取消</button><button class="primary" id="confirmDeletePage">删除页面</button></div>`);$('#confirmDeletePage').onclick=()=>{edit(()=>{doc.pages=doc.pages.filter(p=>p.id!==id);if(pageId===id){pageId=doc.pages[0].id;selection=[]}});hideModal();fitAll()}}
function drawOverlay(){const dpr=engine?.dpr||1,w=viewport.clientWidth,h=viewport.clientHeight;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.lineWidth=1;ctx.font='10px '+M.FONT;ctx.textBaseline='alphabetic';for(const r of records){if(r.parent||!r.visible||!['frame','component'].includes(r.node.type))continue;const p=screen(r.corners[0]);if(p.x<-300||p.x>w+100||p.y<-30||p.y>h+50)continue;ctx.fillStyle=selection.includes(r.node.id)?'#3673F5':'#909BAD';ctx.fillText(r.node.name,p.x,p.y-11)}
function outline(r,color,handles=false){const ps=r.corners.map(screen);ctx.strokeStyle=color;ctx.lineWidth=1;ctx.beginPath();ps.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.stroke();if(handles){for(const p of handlePoints(r).slice(0,8)){ctx.fillStyle='#fff';ctx.strokeStyle=color;ctx.fillRect(p.x-3,p.y-3,6,6);ctx.strokeRect(p.x-3,p.y-3,6,6)}const rot=handlePoints(r)[8],mid=handlePoints(r)[4];ctx.beginPath();ctx.moveTo(mid.x,mid.y);ctx.lineTo(rot.x,rot.y);ctx.stroke();ctx.beginPath();ctx.arc(rot.x,rot.y,3,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.stroke()}}
if(hoverId&&!selection.includes(hoverId)&&!drag&&!penPoints.length){const r=recordMap.get(hoverId);if(r)outline(r,'#3673F577')}
if(selection.length&&!editingId){const rs=selectedRecords();if(rs.length===1){const r=rs[0];outline(r,r.node.type==='component'||r.node.type==='instance'?'#9265D9':'#3673F5',!r.locked&&!vectorEdit);if(!vectorEdit){const p=screen({x:r.bounds.x+r.bounds.w/2,y:r.bounds.y+r.bounds.h}),label=`${Math.round(r.node.w*10)/10} × ${Math.round(r.node.h*10)/10}`,tw=ctx.measureText(label).width;ctx.fillStyle='#3673F5';ctx.beginPath();ctx.roundRect(p.x-tw/2-7,p.y+10,tw+14,20,4);ctx.fill();ctx.fillStyle='#fff';ctx.font='9px '+M.FONT;ctx.fillText(label,p.x-tw/2,p.y+23)}}else{for(const r of rs)outline(r,'#3673F5');const b=selBounds();outline({node:b,corners:[{x:b.x,y:b.y},{x:b.x+b.w,y:b.y},{x:b.x+b.w,y:b.y+b.h},{x:b.x,y:b.y+b.h}]},'#3673F5',true)}}
if(drag?.kind==='marquee'){const a=drag.startScreen,b=drag.lastScreen;ctx.fillStyle='#3673F51A';ctx.strokeStyle='#3673F5';ctx.fillRect(Math.min(a.x,b.x),Math.min(a.y,b.y),Math.abs(b.x-a.x),Math.abs(b.y-a.y));ctx.strokeRect(Math.min(a.x,b.x),Math.min(a.y,b.y),Math.abs(b.x-a.x),Math.abs(b.y-a.y))}
if(drag?.guides){ctx.strokeStyle='#E37C9E';ctx.setLineDash([4,3]);for(const g of drag.guides){ctx.beginPath();if(g.axis==='x'){const x=screen({x:g.value,y:0}).x;ctx.moveTo(x,0);ctx.lineTo(x,h)}else{const y=screen({x:0,y:g.value}).y;ctx.moveTo(0,y);ctx.lineTo(w,y)}ctx.stroke()}ctx.setLineDash([])}
if(penPoints.length){ctx.strokeStyle='#3673F5';ctx.lineWidth=1.5;ctx.beginPath();M.pathCommands(ctx,{points:penPoints.map(p=>({x:screen(p).x,y:screen(p).y,...(p.in?{in:screen(p.in)}:{}),...(p.out?{out:screen(p.out)}:{})})),closed:false});if(penPointer){const p=screen(penPointer);ctx.lineTo(p.x,p.y)}ctx.stroke();for(const p of penPoints)drawAnchor(p,M.identity())}
if(vectorEdit){const r=recordMap.get(vectorEdit);if(r)for(const p of r.node.points||[])drawAnchor(p,r.matrix)}
if(rulers){ctx.fillStyle='#FFFFFFD9';ctx.fillRect(0,0,w,19);ctx.fillRect(0,0,19,h);ctx.fillStyle='#939FB0';ctx.font='8px '+M.FONT;const step=view.zoom<.3?500:view.zoom<1?100:50;for(let x=Math.floor(-view.x/view.zoom/step)*step;x<(w-view.x)/view.zoom;x+=step){const sx=screen({x,y:0}).x;if(sx<20)continue;ctx.fillRect(sx,14,1,5);ctx.fillText(String(x),sx+4,10)}for(let y=Math.floor(-view.y/view.zoom/step)*step;y<(h-view.y)/view.zoom;y+=step){const sy=screen({x:0,y}).y;ctx.fillRect(14,sy,5,1);ctx.save();ctx.translate(9,sy-4);ctx.rotate(-Math.PI/2);ctx.fillText(String(y),0,0);ctx.restore()}}}
function drawAnchor(p,m){const q=screen(M.point(m,p));ctx.lineWidth=1;ctx.strokeStyle='#3673F5';for(const key of ['in','out'])if(p[key]){const h=screen(M.point(m,p[key]));ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(h.x,h.y);ctx.stroke();ctx.beginPath();ctx.arc(h.x,h.y,2.5,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.stroke()}ctx.fillStyle='#fff';ctx.fillRect(q.x-3,q.y-3,6,6);ctx.strokeRect(q.x-3,q.y-3,6,6)}
function handlePoints(r){const c=r.corners.map(screen),mid=(a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2});const mids=[mid(c[0],c[1]),mid(c[1],c[2]),mid(c[2],c[3]),mid(c[3],c[0])];const center=mid(c[0],c[2]),v={x:mids[0].x-center.x,y:mids[0].y-center.y},len=Math.hypot(v.x,v.y)||1;return [...c,...mids,{x:mids[0].x+v.x/len*24,y:mids[0].y+v.y/len*24}]}
function handleHit(p){if(!selection.length||editingId||vectorEdit)return null;const rs=selectedRecords();if(rs.some(r=>r.locked))return null;let r;if(rs.length===1)r=rs[0];else{const b=selBounds();r={node:b,corners:[{x:b.x,y:b.y},{x:b.x+b.w,y:b.y},{x:b.x+b.w,y:b.y+b.h},{x:b.x,y:b.y+b.h}]}}const pts=handlePoints(r);for(let i=0;i<pts.length;i++)if(Math.hypot(pts[i].x-p.x,pts[i].y-p.y)<7){if(i===8&&rs.length!==1)return null;return {index:i,r}}return null}
const hitCanvas=document.createElement('canvas'),hitCtx=hitCanvas.getContext('2d');
function hitTest(p,{deep=true,includeLocked=false,framesOnly=false}={}){for(let i=records.length-1;i>=0;i--){const r=records[i],n=r.node;if(!r.visible||(!includeLocked&&r.locked)||framesOnly&&!['frame','component','instance'].includes(n.type))continue;if(r.clips.some(c=>{const q=M.point(c.inverse,p);return q.x<0||q.y<0||q.x>c.w||q.y>c.h}))continue;const q=M.point(r.inverse,p),tol=4/view.zoom;if(q.x<-tol||q.y<-tol||q.x>n.w+tol||q.y>n.h+tol)continue;if(n.type==='ellipse'&&((q.x-n.w/2)/(n.w/2))**2+((q.y-n.h/2)/(n.h/2))**2>1.08)continue;if(n.type==='path'||n.type==='line'){M.shapePath(hitCtx,n);hitCtx.lineWidth=Math.max(n.strokeWidth||1,8/view.zoom);if(!(n.fillEnabled!==false&&hitCtx.isPointInPath(q.x,q.y))&&!hitCtx.isPointInStroke(q.x,q.y))continue}return r}return null}
function frameLabelHit(p){for(const r of records){if(r.parent||!r.visible||!['frame','component'].includes(r.node.type))continue;const q=screen(r.corners[0]);ctx.font='10px '+M.FONT;if(p.x>=q.x-3&&p.x<=q.x+ctx.measureText(r.node.name).width+10&&p.y>=q.y-27&&p.y<=q.y-5)return r}return null}
function vectorHandleHit(p){if(!vectorEdit)return null;const r=recordMap.get(vectorEdit);if(!r)return null;for(let i=0;i<r.node.points.length;i++){const v=r.node.points[i];for(const k of ['in','out','point']){const q=k==='point'?v:v[k];if(q){const s=screen(M.point(r.matrix,q));if(Math.hypot(s.x-p.x,s.y-p.y)<7)return {index:i,key:k,r}}}}return null}
function snapDelta(dx,dy,b){if(!snap)return {dx,dy,guides:[]};let bestX=7/view.zoom,bestY=7/view.zoom,xFix=0,yFix=0,xGuide=null,yGuide=null;const ids=new Set();selectedNodes().forEach(n=>descendantIds(n,ids));const candidates=records.filter(r=>r.visible&&!ids.has(r.node.id)&&r.node.type!=='text'&&!r.node.locked).slice(0,1000);const xs=[b.x+dx,b.x+b.w/2+dx,b.x+b.w+dx],ys=[b.y+dy,b.y+b.h/2+dy,b.y+b.h+dy];for(const r of candidates){const t=r.bounds;for(const x of [t.x,t.x+t.w/2,t.x+t.w])for(const sx of xs){const diff=x-sx;if(Math.abs(diff)<bestX){bestX=Math.abs(diff);xFix=diff;xGuide=x}}for(const y of [t.y,t.y+t.h/2,t.y+t.h])for(const sy of ys){const diff=y-sy;if(Math.abs(diff)<bestY){bestY=Math.abs(diff);yFix=diff;yGuide=y}}}return {dx:dx+xFix,dy:dy+yFix,guides:[...(xGuide===null?[]:[{axis:'x',value:xGuide}]),...(yGuide===null?[]:[{axis:'y',value:yGuide}])]}}
let lastVectorPoint=null;
