overlay.addEventListener('dblclick',e=>{if(tool==='pen'){if(penPoints.length>2&&Math.hypot(penPoints.at(-1).x-penPoints.at(-2).x,penPoints.at(-1).y-penPoints.at(-2).y)<2/view.zoom)penPoints.pop();finishPen(false);return}const hit=hitTest(world(localPoint(e)));if(!hit)return;if(hit.node.type==='text')startText(hit.node.id);else if(hit.node.type==='path'){select([hit.node.id]);vectorEdit=hit.node.id;toast('拖动锚点编辑；Alt 独立调整手柄；Esc 完成');requestDraw()}else if(hit.node.type==='image'){select([hit.node.id]);assetsReplacement=hit.node.id;$('#imageInput').click()}else if(hit.node.type==='note'){select([hit.node.id]);showModal('编辑便签',`<textarea id="noteEdit" class="inline-edit">${M.esc(hit.node.text||'')}</textarea><div class="modal-footer"><button class="primary" id="noteSave">保存便签</button></div>`);$('#noteSave').onclick=()=>{edit(()=>hit.node.text=$('#noteEdit').value);hideModal()}}});
