function positionTextEditor(){const r=recordMap.get(editingId);if(!r)return;const n=r.node,m=r.matrix;Object.assign(textEditor.style,{left:'0px',top:'0px',width:n.w+'px',minHeight:n.h+'px',fontFamily:n.fontFamily||M.FONT,fontSize:n.fontSize+'px',fontWeight:String(n.fontWeight||400),fontStyle:n.italic?'italic':'normal',lineHeight:String(n.lineHeight||1.5),letterSpacing:(n.letterSpacing||0)+'px',textAlign:n.textAlign||'left',textDecoration:n.decoration||'none',color:n.fill,transform:`matrix(${m[0]*view.zoom},${m[1]*view.zoom},${m[2]*view.zoom},${m[3]*view.zoom},${m[4]*view.zoom+view.x},${m[5]*view.zoom+view.y})`})}
