async function importImageFiles(files,at=null){const list=[...files].filter(f=>f.type.startsWith('image/'));if(!list.length)return;let offset=0;for(const file of list){if(file.size>20*1024*1024){toast('单张图片不能超过 20 MB');continue}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('图片格式无法读取'));i.src=src});if(!img.naturalWidth||img.naturalWidth*img.naturalHeight>100e6)throw Error('图片像素尺寸过大');edit(()=>{if(assetsReplacement){const n=M.find(page().children,assetsReplacement)?.node;if(n){n.src=src;n.imageFit='cover'}assetsReplacement=null}else{const c=at||centerWorld(),scale=Math.min(1,500/img.naturalWidth,500/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;addNode(M.node('image',{name:file.name.replace(/\.[^.]+$/,''),x:c.x-w/2+offset,y:c.y-h/2+offset,w,h,src,imageFit:'cover',fillEnabled:true}));offset+=24}});engine.getImage(src)}catch(err){toast('图片导入失败：'+err.message)}}$('#imageInput').value='';setTool('select');toast(`图片已置入，双击图片可替换`)}
$('#imageInput').addEventListener('change',e=>importImageFiles(e.target.files));$('#projectInput').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>60*1024*1024)throw Error('项目文件不能超过 60 MB');const next=M.validateDocument(JSON.parse(await f.text()));await saveNow();loadDocument(next);toast('项目已打开，所有图层可继续编辑')}catch(err){toast('无法打开：'+err.message)}e.target.value=''});
function loadDocument(next,savedView=null,savedPageId=null){finishText();doc=next;doc.id??=M.uid();pageId=savedPageId&&doc.pages.some(p=>p.id===savedPageId)?savedPageId:doc.pages[0].id;selection=[];history=[];future=[];collapsed=new Set();M.walk(page().children,n=>{if(n.children&&n.type!=='frame')collapsed.add(n.id)});engine?.clearCache();refreshRecords();if(savedView&&Number.isFinite(savedView.zoom)&&savedView.zoom>=.03&&savedView.zoom<=16)view=savedView;else fitAll();changed()}
