function showMenu(items,x,y){hideMenu();const el=$('#menu');el.innerHTML=items.map((item,i)=>item==='-'?'<div class="menu-separator"></div>':item.heading?`<div class="menu-heading">${M.esc(item.heading)}</div>`:`<button class="menu-item" data-menuindex="${i}" ${item.disabled?'disabled':''}><span>${item.icon?icon(item.icon):''}</span><span class="menu-label">${M.esc(item.label)}</span>${item.shortcut?`<kbd>${item.shortcut}</kbd>`:''}</button>`).join('');el.classList.remove('hidden');el.style.left=Math.min(x,innerWidth-el.offsetWidth-10)+'px';el.style.top=Math.min(y,innerHeight-el.offsetHeight-10)+'px';activeMenu=true;el.onclick=e=>{const b=e.target.closest('[data-menuindex]');if(!b)return;const item=items[+b.dataset.menuindex];hideMenu();if(typeof item.action==='function')item.action();else action(item.action)}}
